    'use strict';

    const App = (window.MediaPlayer = window.MediaPlayer || {});
    const Q = App.queue;

    const STATUS = ['idle', 'loading', 'playing', 'paused', 'ended', 'error'];

    function initial(over) {
        return Object.assign({
            status: 'idle',
            id: null,
            positionSec: 0,
            durationSec: null,
            volume: 0.7,
            muted: false,
            error: null,
            queue: Q.create([]),
            counted: false,
        }, over || {});
    }

    /* ── WHEN A PLAY COUNTS ──
       Half the track, or four minutes, whichever comes first. That is the
       scrobbling convention and it is the convention because both halves are
       needed: a fixed number alone never counts a two-minute song, and a
       fraction alone makes you sit through twenty minutes of a live set.

       Counting on load instead would tally everything skipped past in three
       seconds, which is the one number a play count must not be.

       Decided HERE rather than in the shell because it is a decision, which
       is what this module is for. The shell is told COUNT_PLAY and performs
       it, the same way it is told LOAD and sets an src.

       The honest limit: this reads the position, not time actually listened,
       so dragging the scrubber past the halfway mark counts as a play. Fixing
       that means accumulating deltas across seeks, which is real state for a
       number nobody is being graded on. Worth knowing, not worth building. */
    const PLAY_AFTER_SEC = 240;

    function countsAsPlayed(positionSec, durationSec) {
        if (positionSec >= PLAY_AFTER_SEC) return true;
        const d = typeof durationSec === 'number' && isFinite(durationSec) && durationSec > 0
            ? durationSec : null;
        /* An unmeasured duration is the VBR-with-no-Xing case, where the
           fraction cannot be computed at all. Four minutes still applies, so
           such a track counts late rather than never. */
        return d !== null && positionSec >= d / 2;
    }

    function clampVol(v) {
        if (typeof v !== 'number' || !isFinite(v)) return 0;
        return Math.max(0, Math.min(1, v));
    }

    // SAVE_STATE is emitted on the transitions worth persisting and
    // deliberately NOT on TICK. A tick is once a second; writing the library
    // directory once a second is how an SSD earns its retirement, and the
    // position is recoverable to within a second anyway. The shell throttles
    // its own saves on top of this.
